    const std::vector<DirectSpeakersCase>& directSpeakersCases() {
      static const std::vector<DirectSpeakersCase> cases = [] {
        std::vector<DirectSpeakersCase> ret;
        for (const RawCase& r : k_cases) {
          DirectSpeakersCase c;
          c.name = r.name; c.layout = r.layout; c.features = r.features;
          for (int i = 0; i < r.labelsCount; i++) c.speakerLabels.push_back(k_labels[r.labelsOffset + i]);
          c.cartesian = r.cartesian;
          for (int i = 0; i < 3; i++) {
            c.position[i] = r.position[i]; c.hasMin[i] = r.hasMin[i]; c.minimum[i] = r.minimum[i];
            c.hasMax[i] = r.hasMax[i]; c.maximum[i] = r.maximum[i];
          }
          c.screenEdgeLockHorizontal = r.screenEdgeLockH; c.screenEdgeLockVertical = r.screenEdgeLockV;
          c.lfeFreq = r.lfeFreq; c.packFormat = r.packFormat;
          c.gains.assign(k_gains + r.gainsOffset, k_gains + r.gainsOffset + r.numChannels);
          ret.push_back(std::move(c));
        }
        return ret;
      }();
      return cases;
    }

